update tours set i18n = jsonb_build_object('es', '{"name": "Jericoacoara en 1 día", "summary": "Jeri en un día con 4x4, Laguna del Paraíso (entrada aparte), Árbol de la Pereza y atardecer.", "description": "Excursión de un día a Jericoacoara saliendo de Fortaleza, con paseo en 4x4, Laguna del Paraíso (entrada aparte), Árbol de la Pereza y el atardecer en la duna. Pedra Furada es opcional.", "includes": ["Transporte de ida y vuelta", "Paseo en 4x4 incluido", "Laguna del Paraíso (entrada no incluida)", "Árbol de la Pereza", "Pedra Furada (opcional)", "Atardecer", "Tasa ambiental de Jeri no incluida"], "times": "Salidas todos los días", "duration": "Ida y vuelta el mismo día", "location": "Jericoacoara", "extras": [{"name": "Pedra Furada"}, {"name": "Tasa ambiental de Jericoacoara (se paga en el lugar)"}]}'::jsonb) where slug = 'jeri-economy';
